from itertools import combinations

def is_bipartite(edges, n):
    """Check if graph is bipartite and return the partition if so."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            queue = [start]
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False, None
    return True, color

def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find cycles
    from collections import deque

    for start in range(n):
        # BFS from start, tracking path
        visited = {start: [start]}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v == start and len(visited[u]) == length:
                    return True
                if v not in visited:
                    visited[v] = visited[u] + [v]
                    if len(visited[v]) < length:
                        queue.append(v)
    return False

def has_4_cycle(edges, n):
    """Check if graph has a 4-cycle."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # For bipartite graphs, check if any two vertices in same partition share 2+ neighbors
    # More direct: check all pairs of vertices
    for i in range(n):
        for j in range(i+1, n):
            common = set(adj[i]) & set(adj[j])
            if len(common) >= 2:
                return True
    return False

def has_3_cycle(edges, n):
    """Check if graph has a triangle."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k in adj[i] and k > i and k > j:
                    return True
    return False

