n = 13
fixed_edges = [(0, 1), (0, 8)]

# Let's try a greedy approach
# Start with fixed edges, then add more edges avoiding 4-cycles

def try_construct():
    edges = list(fixed_edges)

    # Try all possible edges and greedily add them
    all_possible = []
    for u in range(n):
        for v in range(u+1, n):
            if (u, v) not in fixed_edges:
                all_possible.append((u, v))

    # Try different orderings
    import random
    random.seed(42)

    best_edges = None
    best_count = 0

    for trial in range(1000):
        random.shuffle(all_possible)
        current_edges = list(fixed_edges)

        for edge in all_possible:
            test_edges = current_edges + [edge]
            bip, color = is_bipartite(test_edges, n)
            if not bip:
                continue
            if has_4_cycle(test_edges, n):
                continue
            current_edges = test_edges

        if len(current_edges) > best_count:
            best_count = len(current_edges)
            best_edges = current_edges

    return best_edges, best_count

edges, count = try_construct()
